ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportZawartoscList] @rowVersion bigint AS BEGIN SET NOCOUNT ON;
SELECT (select max(AtW_CzasModyfikacji) from cdn.AtrybutyWartosci join cdn.atrybutyklasy on AtW_AtKId=atk_id where AtK_Format like '@s%' and AtK_Wielowart = 0) AS [@RowVersion] ,( select AtW_ID as [@Id], AtW_Wartosc as [@Value] from cdn.AtrybutyWartosci join cdn.atrybutyklasy on AtW_AtKId=atk_id where (AtW_CzasModyfikacji > @rowVersion OR @rowVersion = 0) AND AtK_Format like '@s%' and AtK_Wielowart = 0 for xml path('Value'), type) for xml path('ListValues') SET NOCOUNT OFF;
END
